Factorial(n):
  if n = 0: return 1
  return n × Factorial(n − 1)

Power(a, n):
  if n = 0: return 1
  return a × Power(a, n − 1)

GCD(a, b):
  if a = 0: return b
  return GCD(b mod a, a)

BinarySearch(A, i, j, x):
  if i > j: return 0
  mid := i + floor((j − i) / 2)
  if A[mid] = x: return mid
  if x < A[mid]:
    return BinarySearch(A, i, mid − 1, x)
  return BinarySearch(A, mid + 1, j, x)

Merge(left, right):
  output := empty list
  while left and right are both nonempty:
    if first(left) ≤ first(right):
      move first(left) to end of output
    else:
      move first(right) to end of output
  append all remaining left items to output
  append all remaining right items to output
  return output
